import re, glob, os
from datetime import date, timedelta

files = sorted(glob.glob('/app/logs/*.log'))
sev_re = re.compile(r'\[(ERROR|WARNING|INFO)\]')

def counts_for(datestr):
    c = {'ERROR':0,'WARNING':0,'INFO':0}
    for f in files:
        d = f.split('/')[-1].split('_')[0]
        if d != datestr: continue
        for line in open(f):
            m = sev_re.search(line)
            if m and m.group(1) in c: c[m.group(1)] += 1
    return c

today = date(2025,8,12)
ranges = {
 'today': [today],
 'last_7_days': [today - timedelta(days=k) for k in range(0,7)],
 'last_30_days': [today - timedelta(days=k) for k in range(0,30)],
 'month_to_date': [date(2025,8,1) + timedelta(days=k) for k in range(0,13)],
 'total': None,
}

summary = {}
for name, days in ranges.items():
    agg = {'ERROR':0,'WARNING':0,'INFO':0}
    if days is None:
        for f in files:
            for line in open(f):
                m = sev_re.search(line)
                if m and m.group(1) in agg: agg[m.group(1)] += 1
    else:
        for d in days:
            for k,v in counts_for(d.isoformat()).items(): agg[k]+=v
    summary[name]=agg

lines = ["period,severity,count"]
for name, _ in ranges.items():
    for sev in ['ERROR','WARNING','INFO']:
        lines.append(f"{name},{sev},{summary[name][sev]}")
open('/app/summary.csv','w').write("\n".join(lines)+"\n")
print("\n".join(lines))
EOF
